package glitch

import data.glitch_lib

suspicious_keywords := {"TODO", "FIXME", "HACK", "WORKAROUND", "BUG", "LATER", "LATER2", "XXX", "HARDCODED", "NOSEC", "TODOSEC", "INSECURE"}

security_critical_attributes := {"password", "api_key", "secret_key", "token", "roles", "permissions", "principal", "cidr_block", "source_ranges", "port", "enabled", "public", "encryption"}

contains_any(str, set) {
    contains(str, set[_])
}

has_suspicious_comment(comment) {
    contains_any(comment.content, suspicious_keywords)
}

has_security_critical_attribute(attr) {
    contains_any(attr.name, security_critical_attributes)
}

is_nearby(comment_line, attribute_line) {
    comment_line >= attribute_line - 5
    comment_line <= attribute_line + 5
}

all_comments(node) = comments {
    comments = {c |
        walk(node, [path, n])
        n.ir_type == "Comment"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    comments := all_comments(parent)
    attributes := glitch_lib.all_attributes(parent)

    suspicious_comments := {c | c := comments[_]; has_suspicious_comment(c)}
    critical_attributes := {a | a := attributes[_]; has_security_critical_attribute(a)}

    comment := suspicious_comments[_]
    nearby_critical_attributes := {a | a := critical_attributes[_]; is_nearby(comment.line, a.line)}
    count(nearby_critical_attributes) > 0

    result := {
        "type": "sec_susp_comm",
        "element": comment,
        "path": parent.path,
        "description": "Suspicious comment found near a security-critical attribute. (CWE-546)"
    }
}

